<script setup lang="ts">
import{computed,nextTick,ref,useId,watch}from'vue';import type{MMentionProps,MMentionOption}from'./types';import{useNativeOwner}from'./shared';import{useReferenceConfig}from'./locale';
const props=withDefaults(defineProps<MMentionProps>(),{prefixes:()=>['@'],rows:3});const emit=defineEmits<{ 'update:modelValue':[value:string];select:[option:MMentionOption,prefix:string] }>();const{t}=useReferenceConfig();const identity=`ui-mention-${useId()}`,input=ref<HTMLTextAreaElement>(),open=ref(false),active=ref(0),start=ref(0),end=ref(0),prefix=ref('@'),query=ref(''),composing=ref(false);const sync=useNativeOwner(input,()=>props.modelValue);const matches=computed(()=>props.options.filter(option=>`${option.label||''} ${option.value}`.toLocaleLowerCase().includes(query.value.toLocaleLowerCase())));const available=computed(()=>matches.value.map((option,index)=>({option,index})).filter(item=>!item.option.disabled));
function inspect(){const control=input.value;if(!control||composing.value||props.disabled||props.readonly){open.value=false;return;}const caret=control.selectionStart,text=control.value.slice(0,caret);let index=-1,found='';for(const marker of props.prefixes){const position=text.lastIndexOf(marker);if(position>index&&(position===0||/\s/.test(text[position-1]!))&&!/\s/.test(text.slice(position+marker.length))){index=position;found=marker;}}if(index<0){open.value=false;return;}start.value=index;end.value=caret;prefix.value=found;query.value=text.slice(index+found.length);active.value=available.value[0]?.index??-1;open.value=true;}
let revision=0;
function inputEvent(){if(composing.value)return;const value=input.value?.value||'',ticket=++revision;emit('update:modelValue',value);inspect();void sync().then(()=>{if(ticket===revision&&props.modelValue!==value)open.value=false;});}
function choose(option:MMentionOption){if(option.disabled||props.disabled||props.readonly||!input.value)return;const value=input.value.value.slice(0,start.value)+prefix.value+option.value+' '+input.value.value.slice(end.value);const caret=start.value+prefix.value.length+option.value.length+1;emit('update:modelValue',value);emit('select',option,prefix.value);open.value=false;void nextTick(()=>{input.value!.value=props.modelValue;input.value!.focus();if(props.modelValue===value)input.value!.setSelectionRange(caret,caret);});}
function key(event:KeyboardEvent){if(event.isComposing||composing.value||!open.value)return;if(event.key==='Escape'){event.preventDefault();open.value=false;}else if(event.key==='ArrowDown'||event.key==='ArrowUp'){event.preventDefault();const index=available.value.findIndex(item=>item.index===active.value);active.value=available.value[(index+(event.key==='ArrowDown'?1:-1)+available.value.length)%available.value.length]?.index??0;}else if(event.key==='Enter'&&matches.value[active.value]){event.preventDefault();choose(matches.value[active.value]!);}else if(event.key==='Tab')open.value=false;}
watch(()=>[props.disabled,props.readonly],()=>{if(props.disabled||props.readonly)open.value=false;});
</script>
<template><div class="ui-ri"><label :for="id||identity" class="ui-ri__label">{{label}}</label><textarea :id="id||identity" ref="input" class="ui-ri__control" :value="modelValue" :name="name" :form="form" :required="required" :disabled="disabled" :readonly="readonly" :rows="rows" :aria-controls="open?identity+'-suggestions':undefined" :aria-expanded="open" :aria-activedescendant="open&&matches[active]?identity+'-option-'+active:undefined" aria-autocomplete="list" @compositionstart="composing=true;open=false" @compositionend="composing=false;inputEvent()" @input="inputEvent" @click="inspect" @keydown="key" @blur="open=false"></textarea><ul v-if="open" :id="identity+'-suggestions'" role="listbox" :aria-label="t('mention.suggestions','提及候选')" class="ui-ri__panel ui-ri__list"><li v-for="(option,index) in matches" :id="identity+'-option-'+index" :key="option.value" role="option" :aria-selected="active===index" :aria-disabled="option.disabled||undefined" @pointerdown.prevent="!option.disabled&&choose(option)"><button type="button" tabindex="-1" class="ui-ri__button" :disabled="option.disabled" @click="choose(option)">{{option.label||option.value}}</button></li><li v-if="!matches.length">{{t('empty','暂无数据')}}</li></ul></div></template>
